import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";

export interface Props extends HTMLAttributes<"span"> {}

const { class: className, ...props } = Astro.props;
---

{/*
  Layout-neutral wrapper: any element inside closes the sheet on click.
  A wrapper (not a button) so composing `<SheetClose><Button/></SheetClose>`
  stays valid HTML — nested buttons get split apart by the parser.
*/}
<span data-sheet-close class={cn("contents", className)} {...props}>
  <slot />
</span>

---
import { cn } from "@/utils/cn";
import type { HTMLAttributes } from "astro/types";
import HugeIcon from "../icon/HugeIcon.astro";
import { Cancel01Icon } from "../icon/icons";

export interface Props extends HTMLAttributes<"div"> {
  side?: "top" | "right" | "bottom" | "left";
  showCloseButton?: boolean;
}

const {
  side = "right",
  showCloseButton = true,
  class: className,
  ...props
} = Astro.props;

const sideStyles = {
  top: "inset-x-0 top-0 border-b",
  right: "inset-y-0 right-0 h-full w-3/4 border-l sm:max-w-sm",
  bottom: "inset-x-0 bottom-0 border-t",
  left: "inset-y-0 left-0 h-full w-3/4 border-r sm:max-w-sm",
};

const classes = cn(
  "fixed z-50 gap-4 bg-background p-6 shadow-lg",
  sideStyles[side],
  className
);
---

<div
  data-sheet-content
  data-side={side}
  role="dialog"
  aria-modal="true"
  class={classes}
  hidden
  {...props}
>
  <slot />
  {showCloseButton && (
    <button
      type="button"
      data-sheet-close
      class="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none"
    >
      <HugeIcon icon={Cancel01Icon} class="size-4" />
      <span class="sr-only">Close</span>
    </button>
  )}
</div>

